const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim();
    if (!input) return;
    const N = parseInt(input, 10);

    const result = [];
    for (let i = 0; i < N; i++) {
        const row = [];
        for (let j = 0; j < N; j++) {
            const val = Math.min(i, j, N - 1 - i, N - 1 - j) + 1;
            row.push(val);
